<script setup lang="ts">
import { computed, reactive } from 'vue';
import { Link, router } from '@inertiajs/vue3';
import AppLayout from '../../Layouts/AppLayout.vue';
import { Activity, CalendarDays, CircleDollarSign, Filter, History, LogIn, Megaphone, RefreshCcw, ShieldCheck, UserRoundCheck, UsersRound } from '@lucide/vue';

type LogRow={id:number;action:string;route_name:string|null;description:string;method:string;subject_type:string|null;subject_id:number|null;ip_address:string|null;occurred_at:string;user:{name:string;role:string}|null};
type Paginated={data:LogRow[];links:Array<{url:string|null;label:string;active:boolean}>;total:number;from:number;to:number};
const props=defineProps<{logs:Paginated;users:Array<{id:number;name:string}>;actions:Array<{value:string;label:string}>;filters:{user?:string;action?:string;from?:string;to?:string};summary:{today:number;actors:number;sensitive:number}}>();
const filters=reactive({user:props.filters.user||'',action:props.filters.action||'',from:props.filters.from||'',to:props.filters.to||''});
const applyFilters=()=>router.get('/activity-log',{...filters},{preserveState:true,replace:true});
const resetFilters=()=>{filters.user='';filters.action='';filters.from='';filters.to='';router.get('/activity-log');};
const actionMeta=(action:string)=>({create:{label:'ایجاد',icon:Activity,class:'audit-create'},update:{label:'ویرایش',icon:Activity,class:'audit-update'},status_change:{label:'تغییر وضعیت',icon:RefreshCcw,class:'audit-status'},attendance:{label:'حضور و غیاب',icon:UserRoundCheck,class:'audit-attendance'},payment:{label:'پرداخت',icon:CircleDollarSign,class:'audit-payment'},notification:{label:'اعلان',icon:Megaphone,class:'audit-notification'},login:{label:'ورود',icon:LogIn,class:'audit-login'},logout:{label:'خروج',icon:LogIn,class:'audit-logout'},delete:{label:'حذف',icon:Activity,class:'audit-delete'}}[action]||{label:'عملیات',icon:Activity,class:'audit-update'});
const formatDate=(value:string)=>new Intl.DateTimeFormat('fa-IR',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value.replace(' ','T')));
const paginationLabel=(label:string)=>label.replace('&laquo; Previous','قبلی').replace('Next &raquo;','بعدی');
const hasFilters=computed(()=>Object.values(filters).some(Boolean));
</script>

<template>
<AppLayout title="تاریخچه فعالیت‌ها" eyebrow="کنترل و شفافیت عملیات باشگاه">
    <section class="audit-hero"><div><p class="section-kicker !text-[#f4a475]">دفتر رویدادهای سامانه</p><h2 class="mt-2 text-xl font-black text-white">هر عملیات مهم، قابل پیگیری است</h2><p class="mt-2 max-w-xl text-[10px] leading-6 text-[#afc1cd]">ورود کاربران، تغییر پرونده‌ها، حضور و غیاب و عملیات مالی با زمان و انجام‌دهنده ثبت می‌شوند.</p></div><History :size="74" class="text-white/10" stroke-width="1"/></section>
    <div class="mt-5 grid gap-3 sm:grid-cols-3"><article class="access-stat"><div><span>عملیات امروز</span><strong>{{summary.today}}</strong></div><Activity :size="22"/></article><article class="access-stat"><div><span>کاربران فعال در ۳۰ روز</span><strong>{{summary.actors}}</strong></div><UsersRound :size="22"/></article><article class="access-stat"><div><span>رویدادهای حساس در ۳۰ روز</span><strong>{{summary.sensitive}}</strong></div><ShieldCheck :size="22"/></article></div>
    <section class="panel-flat mt-5"><div class="panel-head"><div><h3>جست‌وجو در تاریخچه</h3><p>رویدادها را براساس کاربر، نوع عملیات یا بازه زمانی محدود کنید.</p></div><Filter :size="18" class="text-[#d5652b]"/></div><form class="audit-filters" @submit.prevent="applyFilters"><label class="form-label">کاربر<select v-model="filters.user" class="form-input"><option value="">همه کاربران</option><option v-for="user in users" :key="user.id" :value="user.id">{{user.name}}</option></select></label><label class="form-label">نوع عملیات<select v-model="filters.action" class="form-input"><option value="">همه عملیات</option><option v-for="action in actions" :key="action.value" :value="action.value">{{action.label}}</option></select></label><label class="form-label">از تاریخ<input v-model="filters.from" type="date" class="form-input" dir="ltr"></label><label class="form-label">تا تاریخ<input v-model="filters.to" type="date" class="form-input" dir="ltr"></label><div class="flex items-end gap-2"><button class="primary-sport-button h-[41px]"><Filter :size="14"/>اعمال</button><button v-if="hasFilters" type="button" class="secondary-button h-[41px]" @click="resetFilters">پاک کردن</button></div></form></section>
    <section class="panel-flat mt-5"><div class="panel-head"><div><h3>رویدادهای ثبت شده</h3><p>{{logs.total}} عملیات در دفتر فعالیت باشگاه</p></div><CalendarDays :size="18" class="text-[#247c62]"/></div><div class="divide-y divide-[#e5e8e8]"><article v-for="log in logs.data" :key="log.id" class="audit-row"><div class="audit-icon" :class="actionMeta(log.action).class"><component :is="actionMeta(log.action).icon" :size="18"/></div><div class="min-w-0 flex-1"><div class="flex flex-wrap items-center gap-2"><strong>{{log.description}}</strong><span class="audit-chip" :class="actionMeta(log.action).class">{{actionMeta(log.action).label}}</span></div><p class="mt-2">{{log.user?.name||'کاربر مهمان'}}<span v-if="log.user"> · {{log.user.role}}</span><span v-if="log.subject_type"> · {{log.subject_type}} #{{log.subject_id}}</span></p></div><div class="audit-meta"><strong>{{formatDate(log.occurred_at)}}</strong><span dir="ltr">{{log.ip_address||'—'}} · {{log.method}}</span></div></article><div v-if="!logs.data.length" class="p-12 text-center"><History :size="30" class="mx-auto text-[#a5adb1]"/><p class="mt-3 text-[10px] text-[#879198]">در این بازه رویدادی ثبت نشده است.</p></div></div><footer v-if="logs.total" class="flex flex-col gap-3 border-t border-[#e2e5e6] px-5 py-4 sm:flex-row sm:items-center sm:justify-between"><p class="text-[9px] text-[#7d8990]">نمایش {{logs.from||0}} تا {{logs.to||0}} از {{logs.total}}</p><div class="flex gap-1"><Link v-for="link in logs.links" :key="link.label" :href="link.url||'#'" class="pagination-link" :class="{'pagination-active':link.active,'pointer-events-none opacity-40':!link.url}" v-html="paginationLabel(link.label)"/></div></footer></section>
    <div class="audit-privacy mt-5"><ShieldCheck :size="20"/><div><strong>ثبت امن و حداقلی</strong><p>رمز عبور، اطلاعات کارت بانکی و محتوای فرم‌ها در تاریخچه ذخیره نمی‌شوند؛ فقط نوع عملیات، کاربر، زمان و شناسه رکورد نگهداری می‌شود.</p></div></div>
</AppLayout>
</template>
